:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --primary: #e94560;
  --secondary: #0f3460;
  --text: #eaeaea;
  --accent: #f5c542;
  --pixel-size: 2px;
  --font: 16px/1.5 system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--bg);
  background-image: linear-gradient(45deg, var(--bg) 25%, transparent 25%, transparent 75%, var(--bg) 75%),
                    linear-gradient(45deg, var(--bg) 25%, transparent 25%, transparent 75%, var(--bg) 75%);
  background-size: 20px 20px;
  background-position: 0 0, 10px 10px;
  font: var(--font);
  color: var(--text);
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border: 4px solid var(--primary);
  border-radius: 0;
  box-shadow: 8px 8px 0 var(--secondary);
  padding: 32px 24px;
  max-width: 480px;
  width: 100%;
  text-align: center;
  image-rendering: pixelated;
}

.title {
  font-size: 1.5rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 16px;
  text-shadow: 2px 2px 0 var(--secondary);
}

.mode-indicator {
  font-size: 1rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--accent);
  margin-bottom: 8px;
}

.timer-display {
  font-size: 4rem;
  font-weight: bold;
  font-variant-numeric: tabular-nums;
  background: var(--secondary);
  color: var(--text);
  padding: 16px;
  margin: 16px 0 24px;
  border: 4px solid var(--primary);
  letter-spacing: 4px;
  line-height: 1.2;
  min-height: 120px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.controls {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

.btn {
  font: inherit;
  font-size: 1rem;
  font-weight: bold;
  text-transform: uppercase;
  letter-spacing: 1px;
  padding: 12px 24px;
  min-width: 120px;
  background: var(--secondary);
  color: var(--text);
  border: 4px solid var(--primary);
  cursor: pointer;
  transition: background 0.1s, transform 0.1s, box-shadow 0.1s;
  box-shadow: 4px 4px 0 var(--bg);
  image-rendering: pixelated;
}

.btn:hover {
  background: var(--primary);
  color: #fff;
}

.btn:focus-visible {
  outline: 4px solid var(--accent);
  outline-offset: 2px;
}

.btn:active {
  transform: translate(4px, 4px);
  box-shadow: none;
}

@media (max-width: 400px) {
  .timer-display {
    font-size: 3rem;
    min-height: 96px;
    padding: 12px;
  }
  .btn {
    min-width: 100px;
    padding: 10px 16px;
    font-size: 0.9rem;
  }
  .card {
    padding: 24px 16px;
  }
}

const WORK_MINUTES = 25;
const BREAK_MINUTES = 5;
const WORK_SECONDS = WORK_MINUTES * 60;
const BREAK_SECONDS = BREAK_MINUTES * 60;

let mode = 'work';
let remaining = WORK_SECONDS;
let running = false;
let intervalId = null;
let endTimestamp = 0;

const timerDisplay = document.getElementById('timerDisplay');
const modeLabel = document.getElementById('modeLabel');
const startPauseBtn = document.getElementById('startPauseBtn');
const resetBtn = document.getElementById('resetBtn');

function formatTime(seconds) {
  const m = Math.floor(seconds / 60);
  const s = seconds % 60;
  return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
}

function updateDisplay() {
  timerDisplay.textContent = formatTime(remaining);
  modeLabel.textContent = mode === 'work' ? 'Work' : 'Break';
}

function setMode(newMode) {
  mode = newMode;
  remaining = mode === 'work' ? WORK_SECONDS : BREAK_SECONDS;
  updateDisplay();
}

function tick() {
  const now = Date.now();
  const diff = Math.max(0, Math.round((endTimestamp - now) / 1000));
  if (diff !== remaining) {
    remaining = diff;
    updateDisplay();
  }
  if (remaining <= 0) {
    clearInterval(intervalId);
    intervalId = null;
    running = false;
    startPauseBtn.textContent = 'Start';
    startPauseBtn.setAttribute('aria-label', 'Start timer');
    setMode(mode === 'work' ? 'break' : 'work');
    // Auto-start next mode
    startTimer();
  }
}

function startTimer() {
  if (running) return;
  running = true;
  endTimestamp = Date.now() + remaining * 1000;
  intervalId = setInterval(tick, 250);
  startPauseBtn.textContent = 'Pause';
  startPauseBtn.setAttribute('aria-label', 'Pause timer');
}

function pauseTimer() {
  if (!running) return;
  running = false;
  clearInterval(intervalId);
  intervalId = null;
  startPauseBtn.textContent = 'Start';
  startPauseBtn.setAttribute('aria-label', 'Start timer');
}

function resetTimer() {
  pauseTimer();
  setMode('work');
}

startPauseBtn.addEventListener('click', () => {
  if (running) {
    pauseTimer();
  } else {
    startTimer();
  }
});

resetBtn.addEventListener('click', resetTimer);

updateDisplay();
